arguments.command:
cat > tests/lag_alert_test.sh <<'EOF'
#!/bin/bash
fail=0
out=$(NOW=$(date -u -d "2026-11-01T20:00:00Z" +%s) bash ops/lag-alert.sh 2>&1)
tail1=$(tail -1 data/readings/latest.csv | cut -d, -f2)
echo "$out" | grep -q '最大 6 時間' || { echo "lag-alert message should say 最大 6 時間: $out (last=$tail1)"; fail=1; }
echo "$out" | grep -q '24' && { echo "lag-alert still mentions 24"; fail=1; }
exit $fail
EOF
bash tests/lag_alert_test.sh; tail -2 data/readings/latest.csv

